formula:
ready:=BARSCOUNT(CLOSE)>65;
fast:=EMA(CLOSE,12); slow:=EMA(CLOSE,26); dif:=fast-slow; dea:=EMA(dif,9); macd:=2*(dif-dea);
delta:=CLOSE-REF(CLOSE,1); rsi:=100*SMA(MAX(delta,0),14,1)/MAX(SMA(ABS(delta),14,1),0.000001);
raw:=(CLOSE-LLV(LOW,9))/MAX(HHV(HIGH,9)-LLV(LOW,9),0.000001)*100;
k:SMA(raw,3,1),COLORWHITE,LINETHICK2; d:SMA(k,3,1),COLORYELLOW;
kUp:=k>d AND k>REF(k,1);
m5:=MA(CLOSE,5); m20:=MA(CLOSE,20);
tr:=MAX(HIGH-LOW,MAX(ABS(HIGH-REF(CLOSE,1)),ABS(LOW-REF(CLOSE,1)))); atr:=MAX(MA(tr,14),0.000001);
roc5:=(CLOSE/MAX(REF(CLOSE,5),0.000001)-1)*100; roc20:=(CLOSE/MAX(REF(CLOSE,20),0.000001)-1)*100;
pos20:=(CLOSE-LLV(LOW,20))/MAX(HHV(HIGH,20)-LLV(LOW,20),0.000001)*100;
std:=STD(CLOSE,20); bias:=(CLOSE-m20)/atr;
volumeRatio:=VOL/MAX(REF(MA(VOL,20),1),1);
bottomCount:=IF(ISVALID(pos20) AND ISVALID(rsi) AND ISVALID(bias) AND ISVALID(roc20) AND ISVALID(std) AND ISVALID(atr),(pos20<=20)+(rsi<=35)+(bias<=-1)+(roc20<=-8)+(CLOSE<=m20-2*std+0.2*atr),DRAWNULL);
topCount:=IF(ISVALID(bottomCount),(pos20>=85)+(rsi>=68)+(bias>=1)+(roc20>=8)+(CLOSE>=m20+2*std-0.2*atr),DRAWNULL);
bottomRaw:=ready AND bottomCount>=2; topRaw:=ready AND topCount>=2;
bottomSignal:=FILTER(bottomRaw AND NOT REF(bottomRaw,1),10); topSignal:=FILTER(topRaw AND NOT REF(topRaw,1),10);
lowUp:=LLV(LOW,3)>REF(LLV(LOW,3),3);
momentum:=(rsi>REF(rsi,1))+(roc5>REF(roc5,1))+(macd>REF(macd,1));
buyPre:=ready AND BARSLAST(bottomRaw)<25 AND lowUp AND CLOSE>OPEN AND CLOSE>REF(CLOSE,1) AND CLOSE>m5 AND momentum>=2 AND kUp AND volumeRatio>=0.8 AND bias<=0.8;
buySignal:=FILTER(buyPre,8); buyAge:=BARSLAST(buySignal); buyLow:=VALUEWHEN(buySignal,LLV(LOW,3));
neck:=REF(HHV(HIGH,5),1); breakout:=CROSS(CLOSE,neck+0.1*atr);
addPre:=ready AND buyAge<30 AND buyAge>=5 AND breakout AND lowUp AND kUp AND k>=50 AND volumeRatio>=1.1 AND bias<=1.8;
addSignal:=FILTER(addPre,10);
weak:=(rsi<REF(rsi,1))+(roc5<REF(roc5,1))+(macd<REF(macd,1))+(k<REF(k,1));
sellPre:=ready AND BARSLAST(topRaw)<25 AND CLOSE<OPEN AND CLOSE<REF(LOW,1) AND weak>=2 AND k<REF(k,1);
sellSignal:=FILTER(sellPre,10); hasBuy:=buyAge<60; stop:=buyLow-0.15*atr; defense:=IF(hasBuy,stop,DRAWNULL);
fail:=hasBuy AND CLOSE<stop AND REF(CLOSE,1)<REF(stop,1); exitSignal:=FILTER(fail AND NOT REF(fail,1),10);
STICKLINE(kUp,0,k,1.8,0),COLORPINK; STICKLINE(NOT kUp,0,k,1.8,0),COLOROLIVE;
HLINE(20),COLOROLIVE,DOTLINE2; HLINE(50),COLORGRAY,DOTLINE2; HLINE(80),COLORRED,DOTLINE2;
DRAWTEXT(bottomSignal,8,'底部观察',1),COLORYELLOW;
DRAWTEXT(buySignal,20,'试仓',1),COLORRED;
DRAWTEXT(addSignal,35,'加仓',1),COLORMAGENTA;
DRAWTEXT(topSignal,90,'高位观察',1),COLORCYAN;
DRAWTEXT(sellSignal,78,'减仓',1),COLORGREEN;
DRAWTEXT(exitSignal,96,'退出预警',1),COLORWHITE;
TOOLTIP(k,'趋势强度',2,''),COLORWHITE;
TOOLTIP(d,'慢速线',2,''),COLORYELLOW;
TOOLTIP(bottomCount,'底部条件数',0,''),COLORYELLOW;
TOOLTIP(topCount,'高位条件数',0,''),COLORCYAN;
TOOLTIP(volumeRatio,'量比参考',2,'x'),COLORGRAY;
TOOLTIP(defense,'防守参考',3,''),COLORWHITE;
